import sys

acc = {}
out = []
for line in sys.stdin.read().split('\n'):
    p = line.split()
    if not p:
        continue
    c = p[0]
    try:
        if c == 'open':
            n, a = p[1], int(p[2])
            if a < 0:
                out.append('error: invalid amount')
            elif n in acc:
                out.append('error: duplicate account')
            else:
                acc[n] = a
                out.append('ok')
        elif c in ('deposit', 'withdraw'):
            n, a = p[1], int(p[2])
            if a <= 0:
                out.append('error: invalid amount')
            elif n not in acc:
                out.append('error: unknown account ' + n)
            elif c == 'deposit':
                acc[n] += a
                out.append('ok')
            elif acc[n] < a:
                out.append('error: insufficient funds')
            else:
                acc[n] -= a
                out.append('ok')
        elif c == 'transfer':
            f, t, a = p[1], p[2], int(p[3])
            if a <= 0:
                out.append('error: invalid amount')
            elif f not in acc:
                out.append('error: unknown account ' + f)
            elif t not in acc:
                out.append('error: unknown account ' + t)
            elif f == t:
                out.append('error: same account')
            elif acc[f] < a:
                out.append('error: insufficient funds')
            else:
                acc[f] -= a
                acc[t] += a
                out.append('ok')
        elif c == 'balance':
            n = p[1]
            if n not in acc:
                out.append('error: unknown account ' + n)
            else:
                out.append(str(acc[n]))
    except (IndexError, ValueError):
        pass
for n in sorted(acc):
    out.append('%s %d' % (n, acc[n]))
print('\n'.join(out))
